settings.markdownTextPattern:
const entity = data[0];  // since single entity datasource

if (!entity) return 'No data';

const name = entity.ssName || 'Unknown Device';
const isOnline = entity.active === true || entity.active === 'true';

const statusText = isOnline ? 'Online' : 'Offline';
const statusColor = isOnline ? '#2ecc71' : '#e74c3c';
const dotColor = isOnline ? '#2ecc71' : '#e74c3c';

return `
<div class="device-header">
  <div class="device-name">${name}</div>
  <div class="status">
    <span class="status-dot" style="background:${dotColor};"></span>
    <span style="color:${statusColor};">${statusText}</span>
  </div>
</div>
`;

